INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzwerk-Medien immer Kabel sein müssen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch drahtlos möglich"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Netzwerk-Medien für ein IT-System auswähle?', 3, '[{"text": "Übertragungsrate", "correct": true, "because": "Bestimmt Leistung"}, {"text": "Schnellste Installation", "correct": false, "because": "Qualität zählt"}, {"text": "Farbschema", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Typen von Netzwerk-Medien gibt es?', 5, '[{"text": "Kupferkabel", "correct": true, "because": "Für Ethernet"}, {"text": "Glasfaser", "correct": true, "because": "Hohe Bandbreite"}, {"text": "Büromöbel", "correct": false, "because": "Kein Medium"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Glasfaser bietet hohe Bandbreite. b) Funkmedien sind immer langsamer als Kabel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Funk kann schnell sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Netzwerk-Medien für ein IT-System auswähle?', 4, '[{"text": "Bandbreite", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Störanfälligkeit", "correct": false, "because": "Beeinflusst Qualität"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Netzwerk-Medien nur für LAN genutzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch WAN, PAN"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Wahl von Netzwerk-Medien?', 3, '[{"text": "Hohe Übertragungsrate", "correct": true, "because": "Sichert Leistung"}, {"text": "Schnellste Installation", "correct": false, "because": "Qualität zählt"}, {"text": "Weniger Medien", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind bei Netzwerk-Medien entscheidend?', 5, '[{"text": "Bandbreite", "correct": true, "because": "Bestimmt Geschwindigkeit"}, {"text": "Störanfälligkeit", "correct": true, "because": "Beeinflusst Zuverlässigkeit"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Kupferkabel sind günstiger als Glasfaser. b) Funkmedien sind immer unzuverlässig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Funk kann zuverlässig sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um Netzwerk-Medien effektiv auszuwählen?', 4, '[{"text": "Übertragungsrate", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Reichweite", "correct": false, "because": "Bestimmt Einsatz"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Netzwerk-Medien immer kabelgebunden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch drahtlos"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Netzwerk-Medien?', 4, '[{"text": "Hohe Datenrate", "correct": true, "because": "Fördert Leistung"}, {"text": "Flexibilität", "correct": true, "because": "Drahtlos oder kabelgebunden"}, {"text": "Schnellere Installation", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Netzwerk-Medien nur für große Netzwerke geeignet sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Netzwerke"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Netzwerk-Medien für ein IT-System auszuwählen?', 3, '[{"text": "Bandbreite", "correct": true, "because": "Bestimmt Leistung"}, {"text": "Günstigster Preis", "correct": false, "because": "Qualität wichtiger"}, {"text": "Bunte Optik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Glasfaser ist schneller als Kupferkabel. b) Funkmedien sind immer störanfällig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Funk nicht immer störanfällig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei Netzwerk-Medien?', 5, '[{"text": "Reichweite", "correct": true, "because": "Bestimmt Einsatz"}, {"text": "Dämpfung", "correct": true, "because": "Beeinflusst Signal"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Netzwerk-Medien auswähle?', 3, '[{"text": "Bandbreite", "correct": false, "because": "Bestimmt Leistung"}, {"text": "Störanfälligkeit", "correct": false, "because": "Beeinflusst Qualität"}, {"text": "Büroausstattung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Netzwerk-Medien immer physisch?', 3, '[{"text": "Nein", "correct": true, "because": "Auch drahtlos"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Netzwerk-Medien nur für LAN geeignet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch WAN, PAN"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für Netzwerk-Medien?', 4, '[{"text": "Übertragungsrate", "correct": true, "because": "Sichert Leistung"}, {"text": "Schnellste Installation", "correct": false, "because": "Qualität zählt"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]');
